'use strict';
function codeLabel(value){return value&&typeof value==='object'?[value.code,value.description].filter(Boolean).join(' — '):value}
const $=id=>document.getElementById(id), state={page:1,rows:[],more:false,busy:false,loaded:false,request:null,sequence:0};
const esc=s=>String(s??'Not reported').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>n!=null&&n!==''&&Number.isFinite(Number(n))?new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(Number(n)):'Not reported';
function readLocal(key,valid){try{const a=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(a)?a.filter(valid):[]}catch{return []}}
let rules=readLocal('sentinel.rules',r=>r&&typeof r.term==='string'&&Number.isFinite(r.minimum)&&r.minimum>=0);
let watchlist=readLocal('sentinel.watchlist',r=>r&&typeof r.name==='string'&&typeof r.key==='string');
function persist(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{return false}}
const parts=Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone:'America/New_York',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()).map(p=>[p.type,p.value]));
const date=new Date(`${parts.year}-${parts.month}-${parts.day}T12:00:00Z`);$('end').value=date.toISOString().slice(0,10);date.setUTCDate(date.getUTCDate()-30);$('start').value=date.toISOString().slice(0,10);
function showView(id){document.querySelectorAll('.view').forEach(v=>v.hidden=v.id!==id);document.querySelectorAll('[data-view]').forEach(t=>t.classList.toggle('active',t.dataset.view===id))}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>showView(b.dataset.view));
document.querySelectorAll('[data-cue]').forEach(b=>b.onclick=()=>{$('query').value=b.dataset.cue;$('searchBy').value='keyword';$('search').requestSubmit()});
function message(text,error=false){$('message').textContent=text;$('message').classList.toggle('error',error)}
function normalize(r,sub){return {name:r[sub?'Sub-Awardee Name':'Recipient Name'],uei:r[sub?'Sub-Recipient UEI':'Recipient UEI'],amount:r[sub?'Sub-Award Amount':'Award Amount'],id:r[sub?'Sub-Award ID':'Award ID'],date:r[sub?'Sub-Award Date':'Start Date'],end:r['End Date'],description:r[sub?'Sub-Award Description':'Description'],agency:r['Awarding Agency'],prime:sub?r['Prime Recipient Name']:null,primeUei:sub?r['Prime Award Recipient UEI']:null,primeId:sub?r['Prime Award ID']:r['Award ID'],sourceId:sub?r.prime_award_generated_internal_id:r.generated_internal_id,naics:codeLabel(r.NAICS),psc:codeLabel(r.PSC),sub}}
function companyKey(r){return r.uei?`uei:${r.uei}`:`unresolved:${r.sourceId||''}:${r.id}`}
function matched(r,rule){return [r.name,r.uei,r.prime,r.primeUei,r.description,r.id,r.primeId].join(' ').toLowerCase().includes(rule.term.toLowerCase())&&r.amount!=null&&Number(r.amount)>=rule.minimum}
function renderAlerts(){const matches=state.rows.flatMap(row=>rules.filter(r=>matched(row,r)).map(rule=>({row,rule})));$('matches').textContent=state.loaded?matches.length:'—';$('alertFeed').innerHTML=matches.length?matches.map(({row,rule})=>`<article class="alert"><b>${esc(row.name)}</b><p>${esc(money(row.amount))} · ${row.sub?'REPORTED SUBAWARD':'PRIME AWARD'} · ${esc(row.id)}</p><small>Matched “${esc(rule.term)}” ≥ ${esc(money(rule.minimum))}. Growth has not been evaluated.</small></article>`).join(''):'No rule matches in the loaded results.'}
function renderRules(){$('rules').innerHTML=rules.length?rules.map((r,i)=>`<article class="rule"><span>${esc(r.term)} / ≥ ${esc(money(r.minimum))}</span><button data-delete="${i}" aria-label="Delete rule ${esc(r.term)}">DELETE</button></article>`).join(''):'No rules saved.';$('rules').querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{const rule=rules[Number(b.dataset.delete)];if(rule.id){persistentAction('/rules/remove',{id:rule.id});return;}rules.splice(Number(b.dataset.delete),1);persist('sentinel.rules',rules);renderRules()});renderAlerts()}
$('ruleForm').onsubmit=e=>{e.preventDefault();saveAwardRule($('ruleTerm').value.trim(),Number($('ruleAmount').value))};
function groupedCompanies(){const groups=new Map();state.rows.forEach(r=>{const key=companyKey(r);if(!groups.has(key))groups.set(key,{key,name:r.name||'Unknown recipient',uei:r.uei,rows:[]});groups.get(key).rows.push(r)});return [...groups.values()]}
function renderCompanies(){const groups=groupedCompanies();$('companyList').innerHTML=groups.length?groups.map((g,i)=>`<article class="company"><div><h3>${esc(g.name)}</h3><p>UEI: ${esc(g.uei)} · ${g.rows.length} loaded records · ${esc(money(g.rows.reduce((n,r)=>n+(Number(r.amount)||0),0)))}</p><p class="muted">${g.uei?'Exact government recipient identifier':'Identity unresolved; name-only records not merged'}. Loaded amounts are not company revenue.</p></div><button data-watch="${i}" ${watchlist.some(w=>w.key===g.key)?'disabled':''}>${watchlist.some(w=>w.key===g.key)?'WATCHING':'WATCH COMPANY'}</button></article>`).join(''):'Run an award scan to discover recipients.';$('companyList').querySelectorAll('[data-watch]').forEach(b=>b.onclick=()=>{const g=groups[Number(b.dataset.watch)];watchlist.push({key:g.key,name:g.name,uei:g.uei||null});const saved=persist('sentinel.watchlist',watchlist);renderCompanies();if(!saved)$('watchlist').insertAdjacentHTML('afterbegin','<p>Storage unavailable: watchlist lasts only for this session.</p>')});$('watchlist').innerHTML=watchlist.length?watchlist.map((w,i)=>`<article class="company"><div><b>${esc(w.name)}</b><p class="muted">UEI: ${esc(w.uei)} · Saved on this browser</p></div><div><button data-research="${i}">SEARCH AWARDS</button><button data-remove-watch="${i}" aria-label="Remove ${esc(w.name)} from watchlist">REMOVE</button></div></article>`).join(''):'No companies watched.';$('watchlist').querySelectorAll('[data-remove-watch]').forEach(b=>b.onclick=()=>{watchlist.splice(Number(b.dataset.removeWatch),1);persist('sentinel.watchlist',watchlist);renderCompanies()});$('watchlist').querySelectorAll('[data-research]').forEach(b=>b.onclick=()=>{const w=watchlist[Number(b.dataset.research)];$('feed').value='prime';$('searchBy').value='recipient';$('query').value=w.uei||w.name;showView('scanner');$('search').requestSubmit()})}
function render(){const rows=state.rows,sub=state.request?.subawards;$('count').textContent=state.loaded?rows.length:'—';$('total').textContent=state.loaded?money(rows.reduce((n,r)=>n+(Number(r.amount)||0),0)):'—';$('recipientCount').textContent=state.loaded?groupedCompanies().length:'—';$('feedTitle').textContent=sub?'REPORTED SUBAWARD FEED':'PRIME AWARD FEED';$('agencyHeading').textContent=sub?'PRIME / AGENCY':'AGENCY';$('dateHeading').textContent=sub?'SUBAWARD DATE':'START DATE';$('feedHelp').textContent=sub?'Dates filter reported subaward action dates. These are reported relationships, not complete supplier coverage.':'Dates filter award activity; sorting uses the award start date, not discovery time. Keyword search is broader than recipient search.';$('rows').innerHTML=rows.length?rows.map((r,i)=>`<tr><td><b>${esc(r.name)}</b><small>${esc(r.id)}</small></td><td>${r.sub?`<b>${esc(r.prime)}</b><small>${esc(r.agency)}</small>`:esc(r.agency)}</td><td>${esc(money(r.amount))}</td><td>${esc(r.date)}</td><td><button data-inspect="${i}">INSPECT</button></td></tr>`).join(''):`<tr><td colspan="5">${state.busy?'Retrieving records…':'No awards loaded. Run or refine a scan.'}</td></tr>`;$('rows').querySelectorAll('[data-inspect]').forEach(b=>b.onclick=()=>inspect(rows[Number(b.dataset.inspect)]));$('pageLabel').textContent=`PAGE ${state.page}`;renderAlerts();renderCompanies()}
function sourceUrl(r){return r.sourceId?`https://www.usaspending.gov/award/${encodeURIComponent(r.sourceId)}`:'https://www.usaspending.gov/search'}
function inspect(r){state.sequence++;$('detail').innerHTML=`<h3>${esc(r.name)}</h3><dl><dt>${r.sub?'SUBAWARD':'AWARD'} ID</dt><dd>${esc(r.id)}</dd><dt>RECIPIENT UEI</dt><dd>${esc(r.uei)}</dd>${r.sub?`<dt>REPORTED PRIME CONTRACTOR</dt><dd>${esc(r.prime)}</dd><dt>PRIME UEI / AWARD ID</dt><dd>${esc(r.primeUei)} / ${esc(r.primeId)}</dd>`:''}<dt>AGENCY</dt><dd>${esc(r.agency)}</dd><dt>${r.sub?'REPORTED SUBAWARD AMOUNT':'PRIME AWARD AMOUNT'}</dt><dd>${esc(money(r.amount))}</dd><dt>${r.sub?'SUBAWARD ACTION DATE':'PERFORMANCE PERIOD'}</dt><dd>${esc(r.date)}${r.sub?'':` — ${esc(r.end)}`}</dd><dt>NAICS / PSC</dt><dd>${esc(r.naics)} / ${esc(r.psc)}</dd><dt>DESCRIPTION</dt><dd>${esc(r.description)}</dd><dt>IDENTITY STATUS</dt><dd>${r.uei?'UEI supplied by government record.':'No UEI supplied; identity unresolved.'} Public parent, ticker and IPO status not verified.</dd></dl><a href="${sourceUrl(r)}" target="_blank" rel="noopener">${r.sub?'OPEN LINKED PRIME RECORD':'OPEN SOURCE RECORD'}</a><div class="detail-actions"><button id="companyView">VIEW COMPANY</button>${!r.sub&&r.sourceId?'<button id="loadSubawards">TRACE SUBAWARDS</button>':''}</div>${r.sourceId?'<button id="loadFunding">'+(r.sub?'LINKED PRIME FUNDING':'FUNDING HISTORY')+'</button>':''}<div id="subawardDetail"></div>`;$('companyView').onclick=()=>showView('companies');if($('loadFunding'))$('loadFunding').onclick=()=>openFunding(r.sourceId,true);if($('loadSubawards'))$('loadSubawards').onclick=()=>loadSubawards(r,1)}
async function post(endpoint,body){const response=await fetch(`https://api.usaspending.gov/api/v2/${endpoint}/`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:AbortSignal.timeout(30000)});if(!response.ok)throw new Error(`Source returned HTTP ${response.status}`);const data=await response.json();if(!Array.isArray(data.results))throw new Error('Unexpected source response');return data}
async function loadSubawards(row,page){const sequence=++state.sequence,target=$('subawardDetail');target.textContent='Retrieving reported subawards…';try{const data=await post('subawards',{award_id:row.sourceId,page,limit:10,sort:'action_date',order:'desc'});if(sequence!==state.sequence)return;target.innerHTML=`<h3>REPORTED SUBAWARDS / PAGE ${page}</h3><p class="muted">No reported rows does not establish that no subcontractors exist.</p>`+(data.results.length?data.results.map(r=>`<article class="alert"><b>${esc(r.recipient_name)}</b><p>${esc(money(r.amount))} · ${esc(r.action_date)}</p><small>ID: ${esc(r.subaward_number)}</small><p>${esc(r.description)}</p></article>`).join(''):'<p>No reported subawards returned for this prime award.</p>')+`<div class="pager"><button id="subPrevious" ${page<=1?'disabled':''}>PREVIOUS</button><button id="subNext" ${!data.page_metadata?.hasNext?'disabled':''}>NEXT</button></div>`;$('subPrevious').onclick=()=>loadSubawards(row,page-1);$('subNext').onclick=()=>loadSubawards(row,page+1)}catch(e){if(sequence===state.sequence)target.textContent=`Subaward request failed: ${e.message}. Retry by selecting Trace subawards.`}}
async function scan(){if(state.busy)return;state.busy=true;state.loaded=false;state.sequence++;$('scan').disabled=true;$('previous').disabled=true;$('next').disabled=true;message('Retrieving live award records from USAspending…');$('freshness').textContent='SCANNING';state.rows=[];render();$('detail').textContent='Select an award after this scan completes.';try{const data=await post('search/spending_by_award',{...state.request,page:state.page});state.loaded=true;state.rows=data.results.map(r=>normalize(r,state.request.subawards));state.more=Boolean(data.page_metadata?.hasNext);render();if(typeof persistLoadedAwards==='function')await persistLoadedAwards(state.rows);$('freshness').textContent=`RETRIEVED ${new Date().toLocaleTimeString()}`;message(`${state.rows.length} live ${state.request.subawards?'reported subawards':'prime awards'} loaded. Metrics and rule matches describe this page only.`)}catch(e){state.more=false;$('freshness').textContent='SCAN FAILED';message(`Unable to retrieve live records: ${e.message}. No sample data has been substituted.`,true)}finally{state.busy=false;render();$('scan').disabled=false;$('previous').disabled=state.page<=1;$('next').disabled=!state.more}}
function createRequest(){if($('start').value>$('end').value)throw new Error('Start date must be before end date.');const sub=$('feed').value==='sub',term=$('query').value.trim(),filters={award_type_codes:['A','B','C','D'],time_period:[{start_date:$('start').value,end_date:$('end').value}]};if(term){const kind=$('searchBy').value;if(kind==='recipient')filters.recipient_search_text=[term];else if(kind==='award')filters.award_ids=[`"${term.replace(/"/g,'')}"`];else filters.keywords=[term]}if($('minimum').value!=='')filters.award_amounts=[{lower_bound:Number($('minimum').value)}];return {filters,fields:sub?['Sub-Award ID','Sub-Awardee Name','Sub-Recipient UEI','Sub-Award Amount','Sub-Award Date','Sub-Award Description','Prime Recipient Name','Prime Award ID','Prime Award Recipient UEI','Awarding Agency','NAICS','PSC']:['Award ID','Recipient Name','Recipient UEI','Award Amount','Awarding Agency','Start Date','End Date','Description','NAICS','PSC','Last Modified Date'],limit:25,sort:$('sort').value==='amount'?(sub?'Sub-Award Amount':'Award Amount'):(sub?'Sub-Award Date':'Start Date'),order:'desc',subawards:sub}}
$('search').onsubmit=e=>{e.preventDefault();if(state.busy)return;try{state.request=createRequest();state.page=1;scan()}catch(e){message(e.message,true)}};
$('previous').onclick=()=>{if(!state.busy&&state.page>1){state.page--;scan()}};$('next').onclick=()=>{if(!state.busy&&state.more){state.page++;scan()}};
$('clock').textContent=new Date().toLocaleString('en-US',{timeZone:'America/New_York'})+' ET';renderRules();renderCompanies();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_loaded_contract_awards',description:'Read current loaded award data and scan state; does not scan or modify data.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).length)throw new Error('Expected an empty object');return {page:state.page,scanning:state.busy,more:state.more,awards:state.rows,status:$('message').textContent}}})).catch(()=>{})}catch{}}
